rules.logic:
// Hide the promo
element.style.display = 'none';

// If we haven't already injected the redirect banner, do it now
if (document.getElementById('ext-trending-redirect')) return;

const banner = document.createElement('div');
banner.id = 'ext-trending-redirect';
banner.style.cssText = 'display:flex;flex-direction:column;align-items:center;justify-content:center;padding:48px 24px;gap:16px;text-align:center;';

const heading = document.createElement('div');
heading.textContent = '🔥 Discover What\'s Trending';
heading.style.cssText = 'font-size:22px;font-weight:700;color:var(--yt-spec-text-primary,#0f0f0f);';

const sub = document.createElement('div');
sub.textContent = 'Sign in to see your saved videos, or explore popular content right now.';
sub.style.cssText = 'font-size:14px;color:var(--yt-spec-text-secondary,#606060);max-width:420px;';

const btn = document.createElement('a');
btn.href = '/feed/trending';
btn.textContent = 'Go to Trending';
btn.style.cssText = 'display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:10px 20px;border-radius:20px;background:#ff0000;color:#fff;font-size:14px;font-weight:600;text-decoration:none;';

const btn2 = document.createElement('a');
btn2.href = '/feed/explore';
btn2.textContent = 'Explore Popular Videos';
btn2.style.cssText = 'display:inline-flex;align-items:center;gap:8px;padding:10px 20px;border-radius:20px;border:1px solid var(--yt-spec-text-primary,#0f0f0f);color:var(--yt-spec-text-primary,#0f0f0f);font-size:14px;font-weight:600;text-decoration:none;';

const btnRow = document.createElement('div');
btnRow.style.cssText = 'display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin-top:8px;';
btnRow.appendChild(btn);
btnRow.appendChild(btn2);

banner.appendChild(heading);
banner.appendChild(sub);
banner.appendChild(btnRow);

element.parentNode.insertBefore(banner, element);
